FinancialForecast = {
	init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=FinancialForecast");
		if(!app.Config.Calendars || !app.Config.Calendars.primary) {
			error("Primary calendar missing");
			return;
		}

		if(!app.Config.Calendars.PaymentEventName) {
			error("No payment event name configured");
			return;
		}

		var primaryCalendarId = app.Config.Calendars.primary;
		var paymentEventName = app.Config.Calendars.PaymentEventName;
		var startDate = kendo.toString(new Date(), "yyyy-MM-dd");

		var maxActiveTransaction = (await api.get("B2B/ActiveTransaction/FromSystem(SystemId='" + app.Config.B2B.SourceSystem + "')?$orderby=DebtorPaymentDate desc&$top=1")).value;
		if(maxActiveTransaction.length === 0) {
			error("No transactions");
			return;
		}

		var maxPaymentDate = maxActiveTransaction[0].DebtorPaymentDate.split("T")[0];
		var maxQuery =  `Workflow/CalendarEvent?$filter=CalendarId eq ${primaryCalendarId} and Name eq '${paymentEventName}' and date(Start) ge ${maxPaymentDate}&$orderby=Start asc&$top=1`;
		var maxCalendarEvent = (await api.get(maxQuery)).value;

		if(maxCalendarEvent.length === 0) {
			error("No payment events after " + maxPaymentDate);
			return;
		}

		var endDate = maxCalendarEvent[0].Start.split("T")[0];

		var calendarQuery = `Workflow/CalendarEvent?$filter=CalendarId eq ${primaryCalendarId} and Name eq '${paymentEventName}' and date(Start) ge ${startDate} and date(Start) le ${endDate}&$orderby=Start asc`;
		var events = (await api.get(calendarQuery)).value;
		var paymentRunBreakdownData = await FinancialForecast.createDatasourceForCashForecast(app, events); 
		await FinancialForecast.buildCashForecastGrid(container, paymentRunBreakdownData);
    },

    createDatasourceForCashForecast: async function (app, events) {
		var sourceSystem = app.Config.B2B.SourceSystem;
		var earliestEventStartDate = events[0].Start.split("T")[0];
		var allTransactions = (await api.get(`B2B/ActiveTransaction/FromSystem(SystemId='${sourceSystem}')?$filter=DebtorState ne 'Held' and date(DebtorPaymentDate) ge ${earliestEventStartDate}&$select=DebtorPaymentDate,Value,CurrencyId`)).value;

		allTransactions.forEach(at => {
			at.DebtorPaymentDate = new Date(at.DebtorPaymentDate);
		});

		var results = [];
		var currencies = [...new Set(allTransactions.map(at => at.CurrencyId))];

		for(let i = 1; i < events.length; i++) {
			var startDate = new Date(events[i-1].Start.split("T")[0]);
			var endDate = new Date(events[i].Start.split("T")[0]);
			let applicableTransactions = allTransactions.filter(at => at.DebtorPaymentDate >= startDate && at.DebtorPaymentDate < endDate);
			let currencyTotals = currencies.map(c => ({
				CurrencyId: c,
				Total: applicableTransactions.filter(at => at.CurrencyId === c).map(at => at.Value).reduce((a,b) => a + b, 0)
			}));

			for(let j = 0; j < currencyTotals.length; j++) {
				var currencyResult = {
					Start: new Date(startDate),
					End: new Date(endDate),
					CurrencyId: currencyTotals[j].CurrencyId,
					TransactionsNonCumulative: currencyTotals[j].Total,
				};
				currencyResult.TransactionsCumulative = currencyResult.TransactionsNonCumulative + results.filter(r => r.Start < currencyResult.Start).map(r => r.TransactionsNonCumulative).reduce((a,b) => a + b, 0);
				results.push(currencyResult);
			}
		}
		var skippedHowMany = FinancialForecast.skipHowMany(results);
		var manyToTake = (results.length - skippedHowMany) > 6 ? 6 : (results.length - skippedHowMany);

		return {
			culmative: results.slice(skippedHowMany).slice(0, manyToTake).map(r => ({ Start: r.Start, End: r.End, CurrencyId: r.CurrencyId, Total: r.TransactionsCumulative })),
			nonCulmative: results.slice(skippedHowMany).slice(0, manyToTake).map(r => ({ Start: r.Start, End: r.End, CurrencyId: r.CurrencyId, Total: r.TransactionsNonCumulative })),
			skipped: FinancialForecast.skipHowMany(results),
			currencies: currencies
		};
    },

	skipHowMany: function(results) {

		let skipped = 0;
		for(let i = 0; i < results.length; i++) {
			if(results[i].TransactionsNonCumulative === 0 && results[i].TransactionsCumulative === 0) {
				skipped++;
			} else {
				return skipped;
			}
		}
	},

	buildSeries: function(data, type, name, opacity, field) {
		return {
			name: name,
			type: type,
			opacity: opacity,
			style: "smooth",
			line: {
				style: "smooth"
			},
			markers: { visible: true, background: '#ffffff', size: 4 },
			field: "Total",
			categoryField: "Start",
			data: data
		};
	},

    buildCashForecastGrid: function (container, data) {

		var culmativeSeries = [];
		var nonCulmativeSeries = [];
		data.currencies.forEach(c => {
			culmativeSeries.push(FinancialForecast.buildSeries(data.culmative.filter(d => d.CurrencyId === c), "area", "[resource_displayname[accumulativeforecast]] (" + c + ")", 0.7));
			nonCulmativeSeries.push(FinancialForecast.buildSeries(data.nonCulmative.filter(d => d.CurrencyId === c), "line", "[resource_displayname[cashforecastpermonth]] (" + c + ")", 1));
		});

		var chartSeries = culmativeSeries.concat(nonCulmativeSeries).flat();
		var args = {
			series: chartSeries,
			categoryAxis: {	
                field: "Start",
                labels: { template: "#=kendo.toString(value, type.dateFormat)#" }
            },
            tooltip: { visible: true, template: "#: kendo.toString(dataItem.Total, type.moneyFormat)# #: dataItem.CurrencyId# [#: kendo.toString(dataItem.Start, type.dateFormat)# - #: kendo.toString(dataItem.End, type.dateFormat)#)"},
            legend: {
                background: "transparent",
                position: "bottom",
                labels: { font: "12px sans-serif", color: '#000000', margin: 5 },
                padding: { bottom: 50 }
            },
            valueAxis: { labels: { format: "{0:" + type.aggregateMoneyFormat + "}" } }
        };
		console.log({component: "FinancialForecast", args: args, data: data});
		$("[name=chart]", container).kendoChart(args);
    }
}
